/* ==== protocol WholeFrame ========================================================================== */

void test_framing_whole_frame_any_view_print(const test_framing_whole_frame_any_view* v, gmsg_printer* p) {
    switch (v->kind) {
        case TEST_FRAMING_WHOLE_FRAME_READING: test_framing_reading_view_print(&v->as.reading, p); break;
        case TEST_FRAMING_WHOLE_FRAME_NOTE: test_framing_note_view_print(&v->as.note, p); break;
        default: gmsg_print_text(p, "<none>", 6); break;
    }
}

void test_framing_whole_frame_any_message_print(const test_framing_whole_frame_any_message* v, gmsg_printer* p) {
    switch (v->kind) {
        case TEST_FRAMING_WHOLE_FRAME_READING: test_framing_reading_print(&v->as.reading, p); break;
        case TEST_FRAMING_WHOLE_FRAME_NOTE: test_framing_note_print(&v->as.note, p); break;
        default: gmsg_print_text(p, "<none>", 6); break;
    }
}

static const uint8_t test_framing_whole_frame_prefix_[2] = {0x55, 0xAA};
static const gmsg_length_prefixed_config test_framing_whole_frame_framing_ = {{{0x55, 0xAA}, 2}, 2, 1, GMSG_ENDIAN_BIG, INT64_C(2), 5, 64, {false, 0, 0, 0, 0, {0}, {0}, {0}}, 0, false, 0, 0, false};
static gmsg_frame_scan test_framing_whole_frame_scan_(const uint8_t* b, size_t n) { return gmsg_scan_length_prefixed(b, n, &test_framing_whole_frame_framing_); }

/* A validated frame split into its parts (pointers into the frame buffer). */
typedef struct test_framing_whole_frame_frame_ {
    test_framing_whole_frame_header_view header;
    const uint8_t* body;
    size_t body_size;
} test_framing_whole_frame_frame_;

/* Validate one complete frame (as delimited by the scanner) and split it into header and body. */
static gmsg_error test_framing_whole_frame_open_(const uint8_t* frame, size_t size, test_framing_whole_frame_frame_* f) {
    gmsg_error e = GMSG_OK;
    (void)e;
    if (size < 5) return GMSG_ERR_TRUNCATED;
    const size_t interior_n = size - 2 - 0;
    const uint8_t* interior = frame + 2;
    if (interior_n < 3) return GMSG_ERR_TRUNCATED;
    {
        const uint64_t stored = gmsg_load_uint(interior + interior_n - 1, 1, GMSG_ENDIAN_BIG);
        if (stored != (uint64_t)gmsg_sum8_compute(interior + 2, interior_n - 2 - 1)) return GMSG_ERR_BAD_CHECKSUM;
    }
    if ((e = test_framing_whole_frame_header_view_from(interior, 2, &f->header)) != GMSG_OK) return e;
    f->body = interior + 2;
    f->body_size = interior_n - 2 - 1;
    return GMSG_OK;
}

/* Decode the message view selected by the frame's type id (message_type). */
static gmsg_error test_framing_whole_frame_select_(const test_framing_whole_frame_frame_* f, test_framing_whole_frame_any_view* out) {
    switch ((int64_t)test_framing_whole_frame_header_view_id(&f->header)) {
        case INT64_C(1): {  /* Reading */
            out->kind = TEST_FRAMING_WHOLE_FRAME_READING;
            return test_framing_reading_view_from(f->body, f->body_size, &out->as.reading);
        }
        case INT64_C(2): {  /* Note */
            out->kind = TEST_FRAMING_WHOLE_FRAME_NOTE;
            return test_framing_note_view_from(f->body, f->body_size, &out->as.note);
        }
        default: break;
    }
    out->kind = TEST_FRAMING_WHOLE_FRAME_NONE;
    return GMSG_ERR_UNKNOWN_TYPE;
}

static void test_framing_whole_frame_deliver_(const test_framing_whole_frame_callbacks* cb, const test_framing_whole_frame_frame_* f, const test_framing_whole_frame_any_view* v) {
    switch (v->kind) {
        case TEST_FRAMING_WHOLE_FRAME_READING: if (cb->on_reading) cb->on_reading(cb->ctx, &f->header, &v->as.reading); break;
        case TEST_FRAMING_WHOLE_FRAME_NOTE: if (cb->on_note) cb->on_note(cb->ctx, &f->header, &v->as.note); break;
        default: break;
    }
    if (cb->on_frame) cb->on_frame(cb->ctx, &f->header, v);
}

/* Validate a complete frame, select its message and deliver it (C++: P::process). */
static gmsg_error test_framing_whole_frame_process_frame_(const uint8_t* frame, size_t size, const test_framing_whole_frame_callbacks* cb) {
    test_framing_whole_frame_frame_ f;
    test_framing_whole_frame_any_view v;
    gmsg_error e = GMSG_OK;
    if ((e = test_framing_whole_frame_open_(frame, size, &f)) != GMSG_OK) return e;
    if ((e = test_framing_whole_frame_select_(&f, &v)) != GMSG_OK) return e;
    if (cb) test_framing_whole_frame_deliver_(cb, &f, &v);
    return GMSG_OK;
}

gmsg_error test_framing_whole_frame_parse(const uint8_t* data, size_t size, test_framing_whole_frame_any_view* out) {
    test_framing_whole_frame_frame_ f;
    gmsg_error e = GMSG_OK;
    const gmsg_frame_scan s = test_framing_whole_frame_scan_(data, size);
    if (s.kind == GMSG_SCAN_NEED_MORE) return GMSG_ERR_TRUNCATED;
    if (s.kind == GMSG_SCAN_SKIP) return s.error == GMSG_OK ? GMSG_ERR_BAD_SYNC : s.error;
    if ((e = test_framing_whole_frame_open_(data, s.size, &f)) != GMSG_OK) return e;
    return test_framing_whole_frame_select_(&f, out);
}

gmsg_error test_framing_whole_frame_decode(const uint8_t* data, size_t size, test_framing_whole_frame_any_message* out) {
    test_framing_whole_frame_any_view v;
    gmsg_error e = GMSG_OK;
    if ((e = test_framing_whole_frame_parse(data, size, &v)) != GMSG_OK) return e;
    out->kind = v.kind;
    switch (v.kind) {
        case TEST_FRAMING_WHOLE_FRAME_READING: return test_framing_reading_view_to_struct(&v.as.reading, &out->as.reading);
        case TEST_FRAMING_WHOLE_FRAME_NOTE: return test_framing_note_view_to_struct(&v.as.note, &out->as.note);
        default: return GMSG_ERR_UNKNOWN_TYPE;
    }
}

gmsg_error test_framing_whole_frame_process(const uint8_t* data, size_t size, const test_framing_whole_frame_callbacks* cb) {
    const gmsg_frame_scan s = test_framing_whole_frame_scan_(data, size);
    if (s.kind == GMSG_SCAN_NEED_MORE) return GMSG_ERR_TRUNCATED;
    if (s.kind == GMSG_SCAN_SKIP) return s.error == GMSG_OK ? GMSG_ERR_BAD_SYNC : s.error;
    return test_framing_whole_frame_process_frame_(data, s.size, cb);
}

/* stream modes: deliver to callbacks (feed / next), or capture for the pull API */
enum { test_framing_whole_frame_mode_deliver_ = 0, test_framing_whole_frame_mode_capture_ = 1, test_framing_whole_frame_mode_message_ = 2, test_framing_whole_frame_mode_for_ = 3 };

static gmsg_error test_framing_whole_frame_stream_process_(gmsg_stream* gs, uint8_t* frame, size_t n) {
    test_framing_whole_frame_stream* s = (test_framing_whole_frame_stream*)gs;
    test_framing_whole_frame_frame_ f;
    gmsg_error e = GMSG_OK;
    if (s->mode_ == test_framing_whole_frame_mode_deliver_) return test_framing_whole_frame_process_frame_(frame, n, &s->cb);
    if ((e = test_framing_whole_frame_open_(frame, n, &f)) != GMSG_OK) return e;
    if ((e = test_framing_whole_frame_select_(&f, &s->got_.message)) != GMSG_OK) return e;
    s->got_.header = f.header;
    s->got_.bytes = frame;
    s->got_.size = n;
    if (s->mode_ == test_framing_whole_frame_mode_for_ && s->got_.message.kind != s->want_) {
        test_framing_whole_frame_deliver_(&s->cb, &f, &s->got_.message);  /* not the awaited message: to the callbacks */
        s->got_.message.kind = TEST_FRAMING_WHOLE_FRAME_NONE;
    }
    if (s->mode_ == test_framing_whole_frame_mode_message_) {
        switch (s->got_.message.kind) {
            case TEST_FRAMING_WHOLE_FRAME_READING: s->msg_->kind = TEST_FRAMING_WHOLE_FRAME_READING; return test_framing_reading_view_to_struct(&s->got_.message.as.reading, &s->msg_->as.reading);
            case TEST_FRAMING_WHOLE_FRAME_NOTE: s->msg_->kind = TEST_FRAMING_WHOLE_FRAME_NOTE; return test_framing_note_view_to_struct(&s->got_.message.as.note, &s->msg_->as.note);
            default: return GMSG_ERR_UNKNOWN_TYPE;
        }
    }
    return GMSG_OK;
}

bool test_framing_whole_frame_stream_poll(test_framing_whole_frame_stream* s, test_framing_whole_frame_any_view* out) {
    bool ok;
    s->mode_ = test_framing_whole_frame_mode_capture_;
    ok = gmsg_stream_pull(&s->base);
    s->mode_ = test_framing_whole_frame_mode_deliver_;
    if (ok) *out = s->got_.message;
    return ok;
}

bool test_framing_whole_frame_stream_poll_frame(test_framing_whole_frame_stream* s, test_framing_whole_frame_received* out) {
    bool ok;
    s->mode_ = test_framing_whole_frame_mode_capture_;
    ok = gmsg_stream_pull(&s->base);
    s->mode_ = test_framing_whole_frame_mode_deliver_;
    if (ok) *out = s->got_;
    return ok;
}

bool test_framing_whole_frame_stream_poll_message(test_framing_whole_frame_stream* s, test_framing_whole_frame_any_message* out) {
    bool ok;
    s->mode_ = test_framing_whole_frame_mode_message_;
    s->msg_ = out;
    ok = gmsg_stream_pull(&s->base);
    s->mode_ = test_framing_whole_frame_mode_deliver_;
    s->msg_ = NULL;
    return ok;
}

gmsg_poll test_framing_whole_frame_stream_poll_event(test_framing_whole_frame_stream* s, test_framing_whole_frame_event* out) {
    gmsg_step step;
    s->mode_ = test_framing_whole_frame_mode_capture_;
    step = gmsg_stream_step(&s->base);
    s->mode_ = test_framing_whole_frame_mode_deliver_;
    if (step.kind == GMSG_STEP_NEED_MORE) return GMSG_POLL_NEED_MORE;
    if (step.kind == GMSG_STEP_ERROR) {
        out->message.kind = TEST_FRAMING_WHOLE_FRAME_NONE;
        out->error = step.error;
        out->data = step.data;
        out->size = step.size;
        return GMSG_POLL_ERROR;
    }
    out->message = s->got_.message;
    out->error = GMSG_OK;
    out->data = NULL;
    out->size = 0;
    return GMSG_POLL_MESSAGE;
}

bool test_framing_whole_frame_stream_poll_for(test_framing_whole_frame_stream* s, test_framing_whole_frame_kind kind, test_framing_whole_frame_any_view* out) {
    bool hit = false;
    s->mode_ = test_framing_whole_frame_mode_for_;
    s->want_ = kind;
    while (gmsg_stream_pull(&s->base)) {
        if (s->got_.message.kind == kind) {
            *out = s->got_.message;
            hit = true;
            break;
        }
    }
    s->mode_ = test_framing_whole_frame_mode_deliver_;
    return hit;
}

static void test_framing_whole_frame_stream_error_(gmsg_stream* s, gmsg_error e, const uint8_t* data, size_t n) {
    const test_framing_whole_frame_callbacks* cb = &((test_framing_whole_frame_stream*)s)->cb;
    if (cb->on_error) cb->on_error(cb->ctx, e, data, n);
}

gmsg_error test_framing_whole_frame_stream_init(test_framing_whole_frame_stream* s, uint8_t* buf, size_t size) {
    gmsg_memset(s, 0, sizeof *s);  /* callbacks cleared, deliver mode */
    return gmsg_stream_init(&s->base, buf, size, TEST_FRAMING_WHOLE_FRAME_MAX_FRAME, test_framing_whole_frame_scan_, test_framing_whole_frame_stream_process_, test_framing_whole_frame_stream_error_);
}

gmsg_error test_framing_whole_frame_encode_reading(const test_framing_reading* m, uint8_t* out, size_t capacity, size_t* written) {
    test_framing_whole_frame_header h;
    gmsg_memset(&h, 0, sizeof h);
    return test_framing_whole_frame_encode_reading_with_header(&h, m, out, capacity, written);
}

gmsg_error test_framing_whole_frame_encode_reading_with_header(const test_framing_whole_frame_header* hdr, const test_framing_reading* m, uint8_t* out, size_t capacity, size_t* written) {
    test_framing_whole_frame_header h = *hdr;
    gmsg_writer w = gmsg_writer_init(out, capacity);
    gmsg_error e = GMSG_OK;
    if (written) *written = 0;
    if ((e = gmsg_write_bytes(&w, test_framing_whole_frame_prefix_, 2)) != GMSG_OK) return e;
    const size_t header_at = w.pos;
    (void)header_at;
    h.id = ((uint8_t)INT64_C(1));
    if ((e = test_framing_whole_frame_header_write(&h, &w)) != GMSG_OK) return e;
    const size_t body_at = w.pos;
    if ((e = test_framing_reading_write(m, &w)) != GMSG_OK) return e;
    const size_t body_len = w.pos - body_at;
    (void)body_len;
    {
        const int64_t value = (int64_t)(2 + 2 + body_len + 1) - (INT64_C(2));
        if (value < 0 || (uint64_t)value > UINT64_C(255)) return GMSG_ERR_BAD_LENGTH;
        gmsg_write_patch_uint(&w, header_at + 0, 1, GMSG_ENDIAN_BIG, (uint64_t)value);
    }
    const uint64_t cs = (uint64_t)gmsg_sum8_compute(out + body_at, w.pos - body_at);
    if ((e = gmsg_write_uint(&w, 1, GMSG_ENDIAN_BIG, cs)) != GMSG_OK) return e;
    size_t total = w.pos;
    if (written) *written = total;
    return GMSG_OK;
}

gmsg_error test_framing_whole_frame_encode_note(const test_framing_note* m, uint8_t* out, size_t capacity, size_t* written) {
    test_framing_whole_frame_header h;
    gmsg_memset(&h, 0, sizeof h);
    return test_framing_whole_frame_encode_note_with_header(&h, m, out, capacity, written);
}

gmsg_error test_framing_whole_frame_encode_note_with_header(const test_framing_whole_frame_header* hdr, const test_framing_note* m, uint8_t* out, size_t capacity, size_t* written) {
    test_framing_whole_frame_header h = *hdr;
    gmsg_writer w = gmsg_writer_init(out, capacity);
    gmsg_error e = GMSG_OK;
    if (written) *written = 0;
    if ((e = gmsg_write_bytes(&w, test_framing_whole_frame_prefix_, 2)) != GMSG_OK) return e;
    const size_t header_at = w.pos;
    (void)header_at;
    h.id = ((uint8_t)INT64_C(2));
    if ((e = test_framing_whole_frame_header_write(&h, &w)) != GMSG_OK) return e;
    const size_t body_at = w.pos;
    if ((e = test_framing_note_write(m, &w)) != GMSG_OK) return e;
    const size_t body_len = w.pos - body_at;
    (void)body_len;
    {
        const int64_t value = (int64_t)(2 + 2 + body_len + 1) - (INT64_C(2));
        if (value < 0 || (uint64_t)value > UINT64_C(255)) return GMSG_ERR_BAD_LENGTH;
        gmsg_write_patch_uint(&w, header_at + 0, 1, GMSG_ENDIAN_BIG, (uint64_t)value);
    }
    const uint64_t cs = (uint64_t)gmsg_sum8_compute(out + body_at, w.pos - body_at);
    if ((e = gmsg_write_uint(&w, 1, GMSG_ENDIAN_BIG, cs)) != GMSG_OK) return e;
    size_t total = w.pos;
    if (written) *written = total;
    return GMSG_OK;
}

gmsg_error test_framing_whole_frame_encode(const test_framing_whole_frame_any_message* m, uint8_t* out, size_t capacity, size_t* written) {
    switch (m->kind) {
        case TEST_FRAMING_WHOLE_FRAME_READING: return test_framing_whole_frame_encode_reading(&m->as.reading, out, capacity, written);
        case TEST_FRAMING_WHOLE_FRAME_NOTE: return test_framing_whole_frame_encode_note(&m->as.note, out, capacity, written);
        default: break;
    }
    if (written) *written = 0;
    return GMSG_ERR_UNKNOWN_TYPE;
}

