gmsg_error test_framing_escaped_with_end_encode_reading_with_header(const test_framing_escaped_with_end_header* hdr, const test_framing_reading* m, uint8_t* out, size_t capacity, size_t* written) {
    test_framing_escaped_with_end_header h = *hdr;
    gmsg_writer w = gmsg_writer_init(out, capacity);
    gmsg_error e = GMSG_OK;
    if (written) *written = 0;
    if ((e = gmsg_write_bytes(&w, test_framing_escaped_with_end_prefix_, 1)) != GMSG_OK) return e;
    const size_t header_at = w.pos;
    (void)header_at;
    h.id = ((uint8_t)INT64_C(1));
    if ((e = test_framing_escaped_with_end_header_write(&h, &w)) != GMSG_OK) return e;
    const size_t body_at = w.pos;
    if ((e = test_framing_reading_write(m, &w)) != GMSG_OK) return e;
    const size_t body_len = w.pos - body_at;
    (void)body_len;
    {
        const int64_t value = (int64_t)(body_len + 2) - (INT64_C(0));
        if (value < 0 || (uint64_t)value > UINT64_C(255)) return GMSG_ERR_BAD_LENGTH;
        gmsg_write_patch_uint(&w, header_at + 1, 1, GMSG_ENDIAN_BIG, (uint64_t)value);
    }
    const uint64_t cs = (uint64_t)gmsg_crc16_kermit_compute(out + header_at, w.pos - header_at);
    if ((e = gmsg_write_uint(&w, 2, GMSG_ENDIAN_LITTLE, cs)) != GMSG_OK) return e;
    size_t total = w.pos;
    {
        size_t esc_n = 0;
        if ((e = gmsg_escape_in_place(out, capacity, 1, total - 1, &test_framing_escaped_with_end_framing_.escape, &esc_n)) != GMSG_OK) return e;
        total = 1 + esc_n;
    }
    if (capacity - total < 1) return GMSG_ERR_BUFFER_FULL;
    gmsg_memcpy(out + total, test_framing_escaped_with_end_suffix_, 1);
    total += 1;
    if (written) *written = total;
    return GMSG_OK;
}

