/* ==== protocol FixedWithEnd ======================================================================== */

void test_framing_fixed_with_end_any_view_print(const test_framing_fixed_with_end_any_view* v, gmsg_printer* p) {
    switch (v->kind) {
        case TEST_FRAMING_FIXED_WITH_END_READING: test_framing_reading_view_print(&v->as.reading, p); break;
        default: gmsg_print_text(p, "<none>", 6); break;
    }
}

void test_framing_fixed_with_end_any_message_print(const test_framing_fixed_with_end_any_message* v, gmsg_printer* p) {
    switch (v->kind) {
        case TEST_FRAMING_FIXED_WITH_END_READING: test_framing_reading_print(&v->as.reading, p); break;
        default: gmsg_print_text(p, "<none>", 6); break;
    }
}

static const uint8_t test_framing_fixed_with_end_prefix_[1] = {0xC0};
static const uint8_t test_framing_fixed_with_end_suffix_[1] = {0xC1};
static const gmsg_fixed_config test_framing_fixed_with_end_framing_ = {{{0xC0}, 1}, 9, {true, 0xDB, GMSG_ESCAPE_TABLE, 0x00, 3, {0xC0, 0xC1, 0xDB}, {0x10, 0x11, 0x12}, {0x0u, 0x0u, 0x0u, 0x0u, 0x0u, 0x0u, 0x8000003u, 0x0u}}, 1};
static gmsg_frame_scan test_framing_fixed_with_end_scan_(const uint8_t* b, size_t n) { return gmsg_scan_fixed(b, n, &test_framing_fixed_with_end_framing_); }

/* A validated frame split into its parts (pointers into the frame buffer). */
typedef struct test_framing_fixed_with_end_frame_ {
    test_framing_fixed_with_end_header_view header;
    const uint8_t* body;
    size_t body_size;
} test_framing_fixed_with_end_frame_;

/* Validate one complete frame (as delimited by the scanner) and split it into header and body. Unescapes in place. */
static gmsg_error test_framing_fixed_with_end_open_(uint8_t* frame, size_t size, test_framing_fixed_with_end_frame_* f) {
    gmsg_error e = GMSG_OK;
    (void)e;
    if (size < 4) return GMSG_ERR_TRUNCATED;
    size_t interior_n = 0;
    if ((e = gmsg_unescape_in_place(frame + 1, size - 1 - 1, &test_framing_fixed_with_end_framing_.escape, &interior_n)) != GMSG_OK) return e;
    const uint8_t* interior = frame + 1;
    if (interior_n < 2) return GMSG_ERR_TRUNCATED;
    {
        const uint64_t stored = gmsg_load_uint(interior + interior_n - 1, 1, GMSG_ENDIAN_BIG);
        if (stored != (uint64_t)gmsg_xor8_compute(interior, interior_n - 1)) return GMSG_ERR_BAD_CHECKSUM;
    }
    if ((e = test_framing_fixed_with_end_header_view_from(interior, 1, &f->header)) != GMSG_OK) return e;
    f->body = interior + 1;
    f->body_size = interior_n - 1 - 1;
    return GMSG_OK;
}

/* Decode the message view selected by the frame's type id (message_type). */
static gmsg_error test_framing_fixed_with_end_select_(const test_framing_fixed_with_end_frame_* f, test_framing_fixed_with_end_any_view* out) {
    switch ((int64_t)test_framing_fixed_with_end_header_view_id(&f->header)) {
        case INT64_C(1): {  /* Reading */
            out->kind = TEST_FRAMING_FIXED_WITH_END_READING;
            return test_framing_reading_view_from(f->body, f->body_size, &out->as.reading);
        }
        default: break;
    }
    out->kind = TEST_FRAMING_FIXED_WITH_END_NONE;
    return GMSG_ERR_UNKNOWN_TYPE;
}

static void test_framing_fixed_with_end_deliver_(const test_framing_fixed_with_end_callbacks* cb, const test_framing_fixed_with_end_frame_* f, const test_framing_fixed_with_end_any_view* v) {
    switch (v->kind) {
        case TEST_FRAMING_FIXED_WITH_END_READING: if (cb->on_reading) cb->on_reading(cb->ctx, &f->header, &v->as.reading); break;
        default: break;
    }
    if (cb->on_frame) cb->on_frame(cb->ctx, &f->header, v);
}

/* Validate a complete frame, select its message and deliver it (C++: P::process). */
static gmsg_error test_framing_fixed_with_end_process_frame_(uint8_t* frame, size_t size, const test_framing_fixed_with_end_callbacks* cb) {
    test_framing_fixed_with_end_frame_ f;
    test_framing_fixed_with_end_any_view v;
    gmsg_error e = GMSG_OK;
    if ((e = test_framing_fixed_with_end_open_(frame, size, &f)) != GMSG_OK) return e;
    if ((e = test_framing_fixed_with_end_select_(&f, &v)) != GMSG_OK) return e;
    if (cb) test_framing_fixed_with_end_deliver_(cb, &f, &v);
    return GMSG_OK;
}

gmsg_error test_framing_fixed_with_end_parse(uint8_t* data, size_t size, test_framing_fixed_with_end_any_view* out) {
    test_framing_fixed_with_end_frame_ f;
    gmsg_error e = GMSG_OK;
    const gmsg_frame_scan s = test_framing_fixed_with_end_scan_(data, size);
    if (s.kind == GMSG_SCAN_NEED_MORE) return GMSG_ERR_TRUNCATED;
    if (s.kind == GMSG_SCAN_SKIP) return s.error == GMSG_OK ? GMSG_ERR_BAD_SYNC : s.error;
    if ((e = test_framing_fixed_with_end_open_(data, s.size, &f)) != GMSG_OK) return e;
    return test_framing_fixed_with_end_select_(&f, out);
}

gmsg_error test_framing_fixed_with_end_decode(uint8_t* data, size_t size, test_framing_fixed_with_end_any_message* out) {
    test_framing_fixed_with_end_any_view v;
    gmsg_error e = GMSG_OK;
    if ((e = test_framing_fixed_with_end_parse(data, size, &v)) != GMSG_OK) return e;
    out->kind = v.kind;
    switch (v.kind) {
        case TEST_FRAMING_FIXED_WITH_END_READING: return test_framing_reading_view_to_struct(&v.as.reading, &out->as.reading);
        default: return GMSG_ERR_UNKNOWN_TYPE;
    }
}

gmsg_error test_framing_fixed_with_end_process(uint8_t* data, size_t size, const test_framing_fixed_with_end_callbacks* cb) {
    const gmsg_frame_scan s = test_framing_fixed_with_end_scan_(data, size);
    if (s.kind == GMSG_SCAN_NEED_MORE) return GMSG_ERR_TRUNCATED;
    if (s.kind == GMSG_SCAN_SKIP) return s.error == GMSG_OK ? GMSG_ERR_BAD_SYNC : s.error;
    return test_framing_fixed_with_end_process_frame_(data, s.size, cb);
}

/* stream modes: deliver to callbacks (feed / next), or capture for the pull API */
enum { test_framing_fixed_with_end_mode_deliver_ = 0, test_framing_fixed_with_end_mode_capture_ = 1, test_framing_fixed_with_end_mode_message_ = 2, test_framing_fixed_with_end_mode_for_ = 3 };

static gmsg_error test_framing_fixed_with_end_stream_process_(gmsg_stream* gs, uint8_t* frame, size_t n) {
    test_framing_fixed_with_end_stream* s = (test_framing_fixed_with_end_stream*)gs;
    test_framing_fixed_with_end_frame_ f;
    gmsg_error e = GMSG_OK;
    if (s->mode_ == test_framing_fixed_with_end_mode_deliver_) return test_framing_fixed_with_end_process_frame_(frame, n, &s->cb);
    if ((e = test_framing_fixed_with_end_open_(frame, n, &f)) != GMSG_OK) return e;
    if ((e = test_framing_fixed_with_end_select_(&f, &s->got_.message)) != GMSG_OK) return e;
    s->got_.header = f.header;
    s->got_.bytes = frame;
    s->got_.size = n;
    if (s->mode_ == test_framing_fixed_with_end_mode_for_ && s->got_.message.kind != s->want_) {
        test_framing_fixed_with_end_deliver_(&s->cb, &f, &s->got_.message);  /* not the awaited message: to the callbacks */
        s->got_.message.kind = TEST_FRAMING_FIXED_WITH_END_NONE;
    }
    if (s->mode_ == test_framing_fixed_with_end_mode_message_) {
        switch (s->got_.message.kind) {
            case TEST_FRAMING_FIXED_WITH_END_READING: s->msg_->kind = TEST_FRAMING_FIXED_WITH_END_READING; return test_framing_reading_view_to_struct(&s->got_.message.as.reading, &s->msg_->as.reading);
            default: return GMSG_ERR_UNKNOWN_TYPE;
        }
    }
    return GMSG_OK;
}

bool test_framing_fixed_with_end_stream_poll(test_framing_fixed_with_end_stream* s, test_framing_fixed_with_end_any_view* out) {
    bool ok;
    s->mode_ = test_framing_fixed_with_end_mode_capture_;
    ok = gmsg_stream_pull(&s->base);
    s->mode_ = test_framing_fixed_with_end_mode_deliver_;
    if (ok) *out = s->got_.message;
    return ok;
}

bool test_framing_fixed_with_end_stream_poll_frame(test_framing_fixed_with_end_stream* s, test_framing_fixed_with_end_received* out) {
    bool ok;
    s->mode_ = test_framing_fixed_with_end_mode_capture_;
    ok = gmsg_stream_pull(&s->base);
    s->mode_ = test_framing_fixed_with_end_mode_deliver_;
    if (ok) *out = s->got_;
    return ok;
}

bool test_framing_fixed_with_end_stream_poll_message(test_framing_fixed_with_end_stream* s, test_framing_fixed_with_end_any_message* out) {
    bool ok;
    s->mode_ = test_framing_fixed_with_end_mode_message_;
    s->msg_ = out;
    ok = gmsg_stream_pull(&s->base);
    s->mode_ = test_framing_fixed_with_end_mode_deliver_;
    s->msg_ = NULL;
    return ok;
}

gmsg_poll test_framing_fixed_with_end_stream_poll_event(test_framing_fixed_with_end_stream* s, test_framing_fixed_with_end_event* out) {
    gmsg_step step;
    s->mode_ = test_framing_fixed_with_end_mode_capture_;
    step = gmsg_stream_step(&s->base);
    s->mode_ = test_framing_fixed_with_end_mode_deliver_;
    if (step.kind == GMSG_STEP_NEED_MORE) return GMSG_POLL_NEED_MORE;
    if (step.kind == GMSG_STEP_ERROR) {
        out->message.kind = TEST_FRAMING_FIXED_WITH_END_NONE;
        out->error = step.error;
        out->data = step.data;
        out->size = step.size;
        return GMSG_POLL_ERROR;
    }
    out->message = s->got_.message;
    out->error = GMSG_OK;
    out->data = NULL;
    out->size = 0;
    return GMSG_POLL_MESSAGE;
}

bool test_framing_fixed_with_end_stream_poll_for(test_framing_fixed_with_end_stream* s, test_framing_fixed_with_end_kind kind, test_framing_fixed_with_end_any_view* out) {
    bool hit = false;
    s->mode_ = test_framing_fixed_with_end_mode_for_;
    s->want_ = kind;
    while (gmsg_stream_pull(&s->base)) {
        if (s->got_.message.kind == kind) {
            *out = s->got_.message;
            hit = true;
            break;
        }
    }
    s->mode_ = test_framing_fixed_with_end_mode_deliver_;
    return hit;
}

static void test_framing_fixed_with_end_stream_error_(gmsg_stream* s, gmsg_error e, const uint8_t* data, size_t n) {
    const test_framing_fixed_with_end_callbacks* cb = &((test_framing_fixed_with_end_stream*)s)->cb;
    if (cb->on_error) cb->on_error(cb->ctx, e, data, n);
}

gmsg_error test_framing_fixed_with_end_stream_init(test_framing_fixed_with_end_stream* s, uint8_t* buf, size_t size) {
    gmsg_memset(s, 0, sizeof *s);  /* callbacks cleared, deliver mode */
    return gmsg_stream_init(&s->base, buf, size, TEST_FRAMING_FIXED_WITH_END_MAX_FRAME, test_framing_fixed_with_end_scan_, test_framing_fixed_with_end_stream_process_, test_framing_fixed_with_end_stream_error_);
}

gmsg_error test_framing_fixed_with_end_encode_reading(const test_framing_reading* m, uint8_t* out, size_t capacity, size_t* written) {
    test_framing_fixed_with_end_header h;
    gmsg_memset(&h, 0, sizeof h);
    return test_framing_fixed_with_end_encode_reading_with_header(&h, m, out, capacity, written);
}

gmsg_error test_framing_fixed_with_end_encode_reading_with_header(const test_framing_fixed_with_end_header* hdr, const test_framing_reading* m, uint8_t* out, size_t capacity, size_t* written) {
    test_framing_fixed_with_end_header h = *hdr;
    gmsg_writer w = gmsg_writer_init(out, capacity);
    gmsg_error e = GMSG_OK;
    if (written) *written = 0;
    if ((e = gmsg_write_bytes(&w, test_framing_fixed_with_end_prefix_, 1)) != GMSG_OK) return e;
    const size_t header_at = w.pos;
    (void)header_at;
    h.id = ((uint8_t)INT64_C(1));
    if ((e = test_framing_fixed_with_end_header_write(&h, &w)) != GMSG_OK) return e;
    const size_t body_at = w.pos;
    if ((e = test_framing_reading_write(m, &w)) != GMSG_OK) return e;
    const size_t body_len = w.pos - body_at;
    (void)body_len;
    if (body_len > 5) return GMSG_ERR_BAD_LENGTH;
    if ((e = gmsg_write_fill(&w, 0, 5 - body_len)) != GMSG_OK) return e;
    const uint64_t cs = (uint64_t)gmsg_xor8_compute(out + header_at, w.pos - header_at);
    if ((e = gmsg_write_uint(&w, 1, GMSG_ENDIAN_BIG, cs)) != GMSG_OK) return e;
    size_t total = w.pos;
    {
        size_t esc_n = 0;
        if ((e = gmsg_escape_in_place(out, capacity, 1, total - 1, &test_framing_fixed_with_end_framing_.escape, &esc_n)) != GMSG_OK) return e;
        total = 1 + esc_n;
    }
    if (capacity - total < 1) return GMSG_ERR_BUFFER_FULL;
    gmsg_memcpy(out + total, test_framing_fixed_with_end_suffix_, 1);
    total += 1;
    if (written) *written = total;
    return GMSG_OK;
}

gmsg_error test_framing_fixed_with_end_encode(const test_framing_fixed_with_end_any_message* m, uint8_t* out, size_t capacity, size_t* written) {
    switch (m->kind) {
        case TEST_FRAMING_FIXED_WITH_END_READING: return test_framing_fixed_with_end_encode_reading(&m->as.reading, out, capacity, written);
        default: break;
    }
    if (written) *written = 0;
    return GMSG_ERR_UNKNOWN_TYPE;
}

